CREATE OR REPLACE FUNCTION public.guard_phase2_listing() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.readiness_status='draft'; NEW.assurance_state='not_checked'; ELSIF NOT public.is_assurance_staff(auth.uid()) THEN NEW.assurance_state=OLD.assurance_state; NEW.last_audited_at=OLD.last_audited_at; NEW.next_review_at=OLD.next_review_at; IF NEW.readiness_status='approved' THEN NEW.readiness_status=OLD.readiness_status; END IF; END IF; IF NEW.readiness_status='approved' AND (TG_OP='INSERT' OR OLD.readiness_status IS DISTINCT FROM 'approved') AND (public.owns_listing(NEW.id,auth.uid()) OR NOT EXISTS(SELECT 1 FROM public.audits WHERE listing_id=NEW.id AND decision='approved') OR EXISTS(SELECT 1 FROM public.corrective_actions WHERE listing_id=NEW.id AND status<>'closed') OR NOT EXISTS(SELECT 1 FROM public.evidence_documents WHERE listing_id=NEW.id AND review_status='approved' AND scan_status='clean' AND (expires_at IS NULL OR expires_at>=current_date))) THEN RAISE EXCEPTION 'Independent approval, checked current evidence and closed actions required'; END IF; IF NEW.status='approved' AND NEW.readiness_status NOT IN ('not_started','approved') THEN RAISE EXCEPTION 'Readiness approval required before publication'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.guard_phase2_evidence() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.scan_status='pending'; NEW.review_status='pending'; NEW.access_class='restricted'; NEW.uploaded_by=auth.uid(); IF public.evidence_path_listing(NEW.storage_key) IS DISTINCT FROM NEW.listing_id THEN RAISE EXCEPTION 'Evidence path mismatch'; END IF; ELSIF NEW.scan_status IS DISTINCT FROM OLD.scan_status AND auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'Only trusted scan service may set virus scan result'; ELSIF NEW.review_status='approved' AND (NEW.scan_status<>'clean' OR public.owns_listing(NEW.listing_id,auth.uid())) THEN RAISE EXCEPTION 'Independent review and virus scanning required'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.guard_phase2_template_item() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.audits WHERE template_id=CASE WHEN TG_OP='INSERT' THEN NEW.template_id ELSE OLD.template_id END) THEN RAISE EXCEPTION 'Used checklist items are immutable; create a new version'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
CREATE TRIGGER phase2_template_item_guard BEFORE INSERT OR UPDATE OR DELETE ON public.audit_template_items FOR EACH ROW EXECUTE FUNCTION public.guard_phase2_template_item();